const r = await tools.exec_command({
  cmd: "git status --short && git diff -- mod-tome.lua evidence/quality/repair-window-19-20260923/IMPLEMENTATION.md evidence/quality/repair-window-19-20260923/VALIDATION.json && rg -n -F '来决定攻击与伤害' mod-tome.lua && rg -n -F '最主要的理论，由永恒精灵魔导师们得出的，恶魔们似乎来自另一个世界' mod-tome.lua && sed -n '1,240p' evidence/quality/repair-window-19-20260923/IMPLEMENTATION.md && sed -n '1,320p' evidence/quality/repair-window-19-20260923/VALIDATION.json",
  workdir: "/workspace/tome4-chinese-translation",
  yield_time_ms: 10000,
  max_output_tokens: 40000,
  sandbox_permissions: "require_escalated",
  justification: "是否允许我核对当前工作树、精确目标出现位置及现有 evidence 内容？这是实施前的只读基线检查。",
  prefix_rule: ["git", "status"]
});
text(r.output);

const cmds = [
  ["verify", "python3 -B .ai/task/repair-w19-20260923/verify.py"],
  ["lint", "python3 -B tools/i18n lint --strict"],
  ["claims", "python3 -B tools/i18n claims check --registry evidence/quality/semantic-claim-regressions-v1.json --strict"],
  ["diffcheck", "git diff --check"]
];
const results = await Promise.all(cmds.map(async ([name, cmd]) => {
  const r = await tools.exec_command({
    cmd,
    workdir: "/workspace/tome4-chinese-translation",
    yield_time_ms: 30000,
    max_output_tokens: 20000,
    sandbox_permissions: "require_escalated",
    justification: "是否允许我运行本修复窗口明确要求的验证命令？沙箱初始化不可用，因此需在隔离外执行。",
    prefix_rule: name === "verify" ? ["python3", "-B", ".ai/task/repair-w19-20260923/verify.py"] :
                 name === "lint" ? ["python3", "-B", "tools/i18n", "lint"] :
                 name === "claims" ? ["python3", "-B", "tools/i18n", "claims", "check"] :
                 ["git", "diff", "--check"]
  });
  return {name, ...r};
}));
for (const r of results) text(JSON.stringify({name:r.name, exit_code:r.exit_code, output:r.output, session_id:r.session_id}));

const checks = [
  ["final_diff_check", "git diff --check"],
  ["json_check", "jq empty evidence/quality/repair-window-19-20260923/VALIDATION.json"],
  ["target_occurrences", "rg -n -F -e '来决定命中与伤害' -e '来决定攻击与伤害' -e '最主要的理论，由永恒精灵魔导师们得出的，恶魔们似乎来自另一个世界' -e '最主要的理论得到了永恒精灵魔导师们某些研究的支持，该理论认为恶魔们似乎来自另一个世界' mod-tome.lua"],
  ["final_status", "git status --short"],
  ["final_diff_stat", "git diff --stat"],
  ["final_target_diff", "git diff --unified=0 -- mod-tome.lua"]
];
const results = [];
for (const [name, cmd] of checks) {
  const r = await tools.exec_command({
    cmd,
    workdir: "/workspace/tome4-chinese-translation",
    yield_time_ms: 10000,
    max_output_tokens: name === "final_target_diff" ? 30000 : 10000,
    sandbox_permissions: "require_escalated",
    justification: "是否允许我完成最终只读范围审计，并在 evidence 落盘后复跑差异空白检查？",
    prefix_rule: name.startsWith("final_diff") ? ["git", "diff"] :
                 name === "json_check" ? ["jq", "empty"] :
                 name === "target_occurrences" ? ["rg", "-n", "-F"] :
                 ["git", "status"]
  });
  results.push({name, ...r});
}
for (const r of results) text(JSON.stringify({name:r.name, exit_code:r.exit_code, output:r.output}));
